import numpy as np
import datetime

def task_func(arr):
    arr = np.asarray(arr)

    def reverse_words(s):
        text = str(s)
        parts = [part.strip() for part in text.split(".") if part.strip() != ""]
        if not parts:
            return ""
        return ".".join(parts[::-1])

    result = np.empty(arr.shape, dtype=object)
    for idx in np.ndindex(arr.shape):
        result[idx] = reverse_words(arr[idx])

    return result
